```python
import numpy as np

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def smoothed_step(x, alpha=0.2):
    x = np.clip(x, 0, 1)
    k = 1 / (1 - alpha)
    return np.where(x <= alpha, x * k, (1 - alpha) * (1 - x) * k + alpha, 'warning')

def smoothed_linear(x, alpha=0.5):
    x = np.clip(x, 0, 1)
    left = alpha ** 2 * x
    right = (1 - alpha) ** 2 * (1 - x)
    return np.where((x >= alpha) & (x <= 1 - alpha), x - alpha, left + right, 'warning')

def smoothed_sigmoid(x, alpha=0.3):
    x = np.clip(x, 0, 1)
    left = sigmoid(alpha * (1 - x))
    right = sigmoid((1 - alpha) * x)
    return np.where((x >= alpha) | (x <= 1 - alpha), left + right, 'warning')

def smoothed_curve(x, curve='step', alpha=None):
    if curve == 'step':
        return smoothed_step(x, alpha)
    elif curve == 'linear':
        return smoothed_linear(x, alpha)
    elif curve == 'sigmoid':
        return smoothed_sigmoid(x, alpha)
    else:
        raise ValueError('Invalid curve type: {}'.format(curve))

# Example usage
x = np.linspace(0, 1, 100)
for alpha in [0.1, 0.2, 0.3]:
    for curve in ['step', 'linear', 'sigmoid']:
        y = smoothed_curve(x, curve, alpha)
        plt.plot(x, y)
plt.show()
```

